import test from 'node:test';
import assert from 'node:assert/strict';
import {newAfternoonScenario,save,restore} from './simulation.js';
import {conversationDisposition,conversationPurpose,proactiveGreeting} from './social-conversation.js';
import {arrive,resolveEncounter} from './encounters.js';
import {openConversation,respond} from './dialogue.js';
import {currentSchedule} from './days.js';
import {beginPersonalEvent,progressPersonalEvent,personalEventsAt} from './personal-events.js';
import {personalEventPosition} from './personal-event-presence.js';
import {advanceFreeTime} from './free-roam.js';
import {mapEventsAt} from './map-events.js';
import {characterVisual} from './character-visuals.js';
function social(kind='close'){const s=newAfternoonScenario(kind);s.dialogue.engine='generative';s.clock.minute=780;s.location='hall';return s;}
test('unfamiliar people need a concrete reason and do not jump into personal chat after a courtesy exchange',()=>{let s=social('stranger');s.contacts={};for(const id of ['yeogyeong','seoyeon','soyul'])s.relations[id+'>taei']={familiarity:0,trust:0,affection:0,tension:0};const a=arrive(s,'hall');assert.equal(conversationPurpose(a.encounter.action),'return-item');assert.ok(!a.encounter.socialEntry.initiated);const met=resolveEncounter(a.state,a.encounter,true);assert.equal(met.state.dialogue.sessions['1:afternoon:yeogyeong'].entry.stage,'brief');assert.match(met.result.text,/감사|떨어뜨/);assert.ok(met.result.options.every(o=>['listen','introduce','leave'].includes(o.kind)));assert.ok(!/가족|취향|제 생각|레슨/.test(met.result.text));const end=respond(met.state,'yeogyeong','gen:listen');assert.equal(end.result.leave,true);assert.equal(end.state.clock.minute,782);assert.ok(end.state.relations['yeogyeong>taei'].familiarity<4);});
test('affection cannot bypass missing familiarity, trust, boundaries, or current obligations',()=>{const s=social(),r=s.relations['seoyeon>taei'];Object.assign(r,{familiarity:0,trust:0,affection:100,tension:0});assert.equal(conversationDisposition(s,'seoyeon').canInitiate,false);assert.equal(conversationDisposition(s,'seoyeon').canContinue,false);Object.assign(r,{familiarity:12,trust:10,affection:5,tension:0});assert.equal(conversationDisposition(s,'seoyeon').canInitiate,true);r.tension=6;assert.equal(conversationDisposition(s,'seoyeon').canContinue,false);});
test('a familiar interested person can initiate at their real location with a saved cooldown and no free relationship reward',()=>{const s=social(),before=structuredClone(s.relations),a=arrive(s,'hall');assert.ok(a.encounter.socialEntry.initiated);assert.match(a.encounter.text,/먼저 알아보고/);assert.deepEqual(a.state.relations,before);const again=arrive(restore(save(a.state)),'hall');assert.ok(!again.encounter?.socialEntry?.initiated);assert.equal(proactiveGreeting(a.state,'yeogyeong'),null);a.state.clock.minute+=91;assert.ok(proactiveGreeting(a.state,'yeogyeong'));});
test('wanting to talk longer produces a real choice, respects no, and does not reduce affection',()=>{let s=social();s=openConversation(s,'seoyeon').state;const relation=structuredClone(s.relations['seoyeon>taei']);const offered=respond(s,'seoyeon','gen:leave');assert.equal(offered.result.leave,false);assert.ok(offered.result.options.some(o=>o.kind==='stay'));assert.match(offered.result.text,/조금만 더/);const end=respond(restore(save(offered.state)),'seoyeon','gen:leave-final');assert.equal(end.result.leave,true);assert.deepEqual(end.state.relations['seoyeon>taei'],relation);assert.equal(end.state.clock.minute,784);});
test('accepting extra conversation extends it once without trapping the player or farming affinity',()=>{let s=openConversation(social(),'seoyeon').state;s=respond(s,'seoyeon','gen:leave').state;s=respond(s,'seoyeon','gen:stay').state;assert.equal(s.dialogue.sessions['1:afternoon:seoyeon'].entry.offeredContinue,true);const end=respond(s,'seoyeon','gen:leave');assert.equal(end.result.leave,true);});
test('real conversation time allows the NPC to leave for the next place and rejects further stale replies',()=>{let s=social();s.clock.minute=838;s=openConversation(s,'seoyeon').state;const first=s.dialogue.sessions['1:afternoon:seoyeon'].response.options.find(o=>o.id!=='leave');const ended=respond(s,'seoyeon','gen:'+first.id);assert.equal(ended.state.clock.minute,840);assert.equal(currentSchedule(ended.state).seoyeon,'cafe');assert.equal(ended.result.leave,true);assert.throws(()=>respond(ended.state,'seoyeon','gen:listen'));});
test('leaving an unfinished event releases its person and map queries cannot resurrect a remote reservation',()=>{let s=social();s.clock.minute=830;s=beginPersonalEvent(s,'seoyeon');s=progressPersonalEvent(s,'ask');assert.equal(personalEventPosition(s,'seoyeon'),'hall');s.location='library';assert.equal(personalEventPosition(s,'seoyeon'),null);assert.equal(currentSchedule(s).seoyeon,'cafe');const before=save(s);assert.ok(!personalEventsAt(s,'hall').some(e=>e.person==='seoyeon'));assert.ok(!mapEventsAt(s,'hall').some(e=>e.id==='seoyeon'));assert.equal(save(s),before);s=advanceFreeTime(s,1);assert.equal(s.personalEvents.active,null);assert.equal(s.personalEvents.records.seoyeon.status,'paused');assert.deepEqual(s.personalEvents.records.seoyeon.choices,['ask']);});
test('ordinary poses use twelve unique full-body cells and strong emotions keep expression portraits',()=>{const cells=new Set();for(const id of ['taei','seoyeon','yeogyeong','soyul','iseo','dogyeom','jihoo','naeun','dohyun','dayeon','chaerin','junseo']){const v=characterVisual(id,{emotion:'neutral'});assert.equal(v.mode,'fullbody');cells.add(v.sheet+':'+v.x+':'+v.y);assert.equal(characterVisual(id,{emotion:'worried'}).mode,'expression');}assert.equal(cells.size,12);assert.equal(characterVisual('unknown'),null);});
test('knowing a name or having high affection does not unlock an intimate personal event',()=>{const s=social();s.relations['seoyeon>taei']={familiarity:0,trust:0,affection:100,tension:0};assert.ok(!personalEventsAt(s).some(e=>e.person==='seoyeon'));assert.throws(()=>beginPersonalEvent(s,'seoyeon'));s.relations['seoyeon>taei']={familiarity:3,trust:2,affection:0,tension:0};assert.ok(personalEventsAt(s).some(e=>e.person==='seoyeon'));});
test('a pending personal obligation blocks initiating or extending chat despite high affinity',()=>{const s=social();s.appointments.push({person:'seoyeon',day:s.day,status:'pending',kind:'activity',minute:785,location:'gym',label:'다른 약속'});const d=conversationDisposition(s,'seoyeon');assert.equal(d.mustGo,true);assert.equal(d.canInitiate,false);assert.equal(d.canContinue,false);});
test('overhearing friends does not invite a stranger into private conversation or automatically exchange names',async()=>{const {groupDialogue,respondGroup}=await import('./dialogue.js');const s=social('first');s.contacts={};for(const id of ['seoyeon','soyul'])s.relations[id+'>taei']={familiarity:0,trust:0,affection:0,tension:0};assert.match(groupDialogue(s).at(-1).text,/길을 막/);const denied=respondGroup(s,'include');assert.match(denied.lines[0].text,/저희끼리/);assert.ok(!denied.state.contacts.soyul?.introduced);assert.deepEqual(denied.state.relations,s.relations);const met=respondGroup(s,'names');assert.equal(met.state.contacts.soyul.introduced,true);assert.equal(met.state.contacts.seoyeon.introduced,true);assert.deepEqual(met.state.relations,s.relations);});
